{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.metafields_data_cleaned_v1 AS WITH image_map AS ( SELECT UPPER(TRIM(sku_group_raw)) AS sku_group, image_url FROM ( SELECT CASE WHEN UPPER(TRIM(variant.value:sku::STRING)) LIKE \'4MTL000%\' THEN TRIM(variant.value:sku::STRING) WHEN UPPER(variant.value:sku::STRING) LIKE \'4C-%\' OR UPPER(variant.value:sku::STRING) LIKE \'MP-%\' OR UPPER(variant.value:sku::STRING) LIKE \'FK-%\' THEN SPLIT_PART(variant.value:sku::STRING,\'-\',1)||\'-\'||SPLIT_PART(variant.value:sku::STRING,\'-\',2)||\'-\'||SPLIT_PART(variant.value:sku::STRING,\'-\',3) WHEN UPPER(variant.value:sku::STRING) LIKE \'SH%\' THEN LEFT(variant.value:sku::STRING, LENGTH(UPPER(variant.value:sku::STRING)) - POSITION(\'-\' IN REVERSE(UPPER(variant.value:sku::STRING)))) WHEN POSITION(\'-\' IN variant.value:sku::STRING) > 0 THEN SPLIT_PART(variant.value:sku::STRING,\'-\',1)||\'-\'||SPLIT_PART(variant.value:sku::STRING,\'-\',2) ELSE variant.value:sku::STRING END AS sku_group_raw, image.value:\"preview\":\"image\":\"url\"::STRING AS image_url, image.index AS idx FROM snitch_db.maplemonk.new_meafields_product_products_graph_ql t, LATERAL FLATTEN(input => PARSE_JSON(t.media)) AS image, LATERAL FLATTEN(input => PARSE_JSON(t.variants)) AS variant WHERE image.value:\"mediaContentType\"::STRING = \'IMAGE\' ) QUALIFY ROW_NUMBER() OVER (PARTITION BY UPPER(TRIM(sku_group_raw)) ORDER BY idx) = 1 ), product_metafields AS ( SELECT CASE WHEN UPPER(TRIM(variant.value:sku::STRING)) LIKE \'4MTL000%\' THEN TRIM(variant.value:sku::STRING) WHEN UPPER(variant.value:sku::STRING) LIKE \'4C-%\' OR UPPER(variant.value:sku::STRING) LIKE \'MP-%\' OR UPPER(variant.value:sku::STRING) LIKE \'FK-%\' THEN SPLIT_PART(variant.value:sku::STRING,\'-\',1)||\'-\'||SPLIT_PART(variant.value:sku::STRING,\'-\',2)||\'-\'||SPLIT_PART(variant.value:sku::STRING,\'-\',3) WHEN UPPER(variant.value:sku::STRING) LIKE \'SH%\' THEN LEFT(variant.value:sku::STRING, LENGTH(UPPER(variant.value:sku::STRING)) - POSITION(\'-\' IN REVERSE(UPPER(variant.value:sku::STRING)))) WHEN POSITION(\'-\' IN variant.value:sku::STRING) > 0 THEN SPLIT_PART(variant.value:sku::STRING,\'-\',1)||\'-\'||SPLIT_PART(variant.value:sku::STRING,\'-\',2) ELSE variant.value:sku::STRING END AS sku_group, MAX(t.producttype) AS category, MAX(t.title) AS title, MAX(IFF(REPLACE(m.value:key,\'\"\',\'\') = \'print_design\', REPLACE(m.value:value,\'\"\',\'\'), NULL)) AS print_design, MAX(IFF(REPLACE(m.value:key,\'\"\',\'\') = \'collar\', REPLACE(m.value:value,\'\"\',\'\'), NULL)) AS collar, MAX(IFF(REPLACE(m.value:key,\'\"\',\'\') = \'material\', REPLACE(m.value:value,\'\"\',\'\'), NULL)) AS material, MAX(IFF(REPLACE(m.value:key,\'\"\',\'\') = \'sleeves_type\', REPLACE(m.value:value,\'\"\',\'\'), NULL)) AS sleeves_type, MAX(IFF(REPLACE(m.value:key,\'\"\',\'\') = \'fit\', REPLACE(m.value:value,\'\"\',\'\'), NULL)) AS fit, MAX(IFF(REPLACE(m.value:key,\'\"\',\'\') = \'style\', REPLACE(m.value:value,\'\"\',\'\'), NULL)) AS style, COALESCE( MAX(IFF(UPPER(TRIM(o.value:name::STRING)) IN (\'COLOR\',\'COLOUR\'), REPLACE(REPLACE(REPLACE(o.value:values,\'[\',\'\'),\']\',\'\'),\'\"\',\'\'), NULL)), MAX(IFF(TRY_TO_NUMBER(REPLACE(o.value:position,\'\"\',\'\')) = 1 AND UPPER(TRIM(o.value:name::STRING)) NOT IN (\'SIZE\',\'TITLE\',\'DENOMINATIONS\',\'MATERIAL\',\'0\'), REPLACE(REPLACE(REPLACE(o.value:values,\'[\',\'\'),\']\',\'\'),\'\"\',\'\'), NULL)) ) AS color FROM snitch_db.maplemonk.new_meafields_product_products_graph_ql AS t, LATERAL FLATTEN(input => PARSE_JSON(t.variants)) AS variant, LATERAL FLATTEN(input => t.metafields) AS m, LATERAL FLATTEN(input => t.options) AS o GROUP BY 1 ), enriched AS ( SELECT pm.*, CASE UPPER(TRIM(REGEXP_REPLACE(SPLIT_PART(pm.print_design, \',\', 1), \'\\s+\', \' \'))) WHEN \'CHECKS\' THEN \'Checks\' WHEN \'CHECKED\' THEN \'Checks\' WHEN \'GINGHAM\' THEN \'Checks\' WHEN \'PLAID\' THEN \'Checks\' WHEN \'COLOURBLOCKED\' THEN \'Colourblocked\' WHEN \'COLORBLOCKED\' THEN \'Colourblocked\' WHEN \'EMBROIDERED\' THEN \'Embroidered\' WHEN \'EMBELLISHED\' THEN \'Embroidered\' WHEN \'EMBROIDERY\' THEN \'Embroidered\' WHEN \'SELF-EMBROIDERED\' THEN \'Embroidered\' WHEN \'GRAPHIC PRINT\' THEN IFF(UPPER(TRIM(pm.category))=\'T-SHIRTS\',\'Graphic Print\',\'Printed\') WHEN \'GRAPHIC PRINTED\' THEN IFF(UPPER(TRIM(pm.category))=\'T-SHIRTS\',\'Graphic Print\',\'Printed\') WHEN \'JACQUARD\' THEN \'Jacquard\' WHEN \'OMBRE\' THEN \'Ombre\' WHEN \'POLKA DOT\' THEN \'Polka Dots\' WHEN \'POLKA DOTS\' THEN \'Polka Dots\' WHEN \'POPLIN\' THEN \'Poplin\' WHEN \'STRIPES\' THEN \'Stripes\' WHEN \'STRIPE\' THEN \'Stripes\' WHEN \'TEXTURED\' THEN \'Textured\' WHEN \'SELF-DESIGN\' THEN \'Textured\' WHEN \'SELF DESIGN\' THEN \'Textured\' WHEN \'SEFL-DESIGN\' THEN \'Textured\' WHEN \'SELF-DEIGN\' THEN \'Textured\' WHEN \'KNITTED\' THEN \'Textured\' WHEN \'TIE & DYE\' THEN \'Tie & Dye\' WHEN \'TYE & DYE\' THEN \'Tie & Dye\' WHEN \'PLAIN\' THEN \'Solid\' WHEN \'SOLID\' THEN \'Solid\' WHEN \'DISTRESSED\' THEN \'Others\' WHEN \'COLLEGE WEAR\' THEN \'Others\' WHEN \'CASUAL WEAR\' THEN \'Others\' WHEN \'PRINTED\' THEN \'Printed\' WHEN \'ABSTRACT\' THEN \'Printed\' WHEN \'FLORAL\' THEN \'Printed\' WHEN \'GEOMETRIC\' THEN \'Printed\' WHEN \'ANIMAL PRINT\' THEN \'Printed\' WHEN \'CAMOUFLAGE\' THEN \'Printed\' WHEN \'APPLIQUE\' THEN \'Printed\' WHEN \'ACID WASHED\' THEN \'Printed\' WHEN \'MARBLE\' THEN \'Printed\' ELSE \'Others\' END AS design_first_bucket FROM product_metafields pm ), master_metafields AS ( SELECT UPPER(TRIM(e.sku_group)) AS sku_group, UPPER(TRIM(e.title)) AS product_name, UPPER(TRIM(e.category)) AS category, CASE WHEN UPPER(e.style) LIKE \'%BISMIL%\' THEN \'Bismil\' WHEN UPPER(e.style) LIKE \'%CATCH%\' THEN \'Catch Me If You Can\' WHEN UPPER(e.style) LIKE \'%CORE%\' THEN \'Core Lab\' WHEN UPPER(e.style) LIKE \'%GRIND%\' THEN \'Grind\' WHEN UPPER(e.style) LIKE \'%HEARTS%\' THEN \'King of Hearts\' WHEN UPPER(e.style) LIKE \'%CHECKOUT%\' THEN \'Late Checkout\' WHEN UPPER(e.style) LIKE \'%LEGACY%\' THEN \'Legacy\' WHEN UPPER(e.style) LIKE \'%YACHT%\' THEN \'Yacht Club\' WHEN UPPER(e.style) LIKE \'%MEDITER%\' THEN \'Mediterranean Mosaic\' WHEN UPPER(e.style) LIKE \'%STREET%\' THEN \'Street FC\' WHEN UPPER(e.style) LIKE \'%RECEIPTS%\' THEN \'Receipts\' WHEN UPPER(e.style) LIKE \'%REVOLUTION%\' THEN \'Revolution\' WHEN UPPER(e.style) LIKE \'%ROOTED%\' THEN \'Rooted In Nature\' WHEN UPPER(e.style) LIKE \'%SIRAJ%\' THEN \'Siraj\' WHEN UPPER(e.style) LIKE \'%TECHNICAL%\' THEN \'Technical\' WHEN UPPER(e.style) LIKE \'%STITCHLESS%\' THEN \'Stitchless\' WHEN UPPER(e.style) LIKE \'%STARS%\' THEN \'Stars Within\' WHEN UPPER(e.style) LIKE \'%GRASS%\' THEN \'Touch Grass Club\' WHEN UPPER(e.style) LIKE \'%UTOPIA%\' THEN \'Utopia\' WHEN UPPER(e.style) LIKE \'%VELVET%\' THEN \'Velvet\' ELSE gc.collection END AS collection, CASE WHEN UPPER(TRIM(e.category)) NOT IN (\'CO-ORDS\',\'HOODIES\',\'INNER WEAR\',\'JACKETS\',\'OVERSHIRT\',\'PYJAMAS\',\'SHIRTS\',\'SWEATERS\',\'SWEATSHIRTS\',\'T-SHIRTS\') THEN \'No_Design\' WHEN e.print_design IS NULL OR TRIM(e.print_design) = \'\' THEN \'No_Design\' WHEN e.design_first_bucket = \'Printed\' AND UPPER(e.print_design) LIKE \'%POLKA DOT%\' THEN \'Polka Dots\' WHEN e.design_first_bucket = \'Printed\' AND UPPER(TRIM(e.category)) = \'T-SHIRTS\' AND UPPER(e.print_design) LIKE \'%GRAPHIC PRINT%\' THEN \'Graphic Print\' ELSE e.design_first_bucket END AS designs, CASE WHEN UPPER(TRIM(e.category)) = \'BLAZERS\' THEN \'Blazers\' WHEN UPPER(TRIM(REGEXP_REPLACE(e.collar,\'\\s+\',\' \'))) = \'CREW\' AND UPPER(TRIM(e.category)) IN (\'JOGGERS & TRACKPANTS\',\'SHORTS\') THEN \'No_Collar\' WHEN UPPER(TRIM(REGEXP_REPLACE(e.collar,\'\\s+\',\' \'))) = \'NOTCH\' AND UPPER(TRIM(e.category)) = \'JACKETS\' THEN \'Others\' WHEN e.collar IS NULL OR TRIM(e.collar) = \'\' THEN \'No_Collar\' ELSE CASE UPPER(TRIM(REGEXP_REPLACE(e.collar,\'\\s+\',\' \'))) WHEN \'BASEBALL\' THEN \'Others\' WHEN \'BUTTON DOWN\' THEN \'Classic\' WHEN \'BUTTON-DOWN\' THEN \'Classic\' WHEN \'CHINESE\' THEN \'Mandarin\' WHEN \'CLASSIC\' THEN \'Classic\' WHEN \'CREW\' THEN \'Round\' WHEN \'CUBAN\' THEN \'Cuban\' WHEN \'CUT AND SEW\' THEN \'Others\' WHEN \'CUTAWAY\' THEN \'Classic\' WHEN \'HALF ZIP\' THEN \'Zip\' WHEN \'HIGH NECK\' THEN \'High Neck\' WHEN \'HOODED\' THEN \'Hooded\' WHEN \'LAPEL\' THEN \'Blazers\' WHEN \'MANDARIN\' THEN \'Mandarin\' WHEN \'MOCK\' THEN \'High Neck\' WHEN \'MOCK NECK\' THEN \'High Neck\' WHEN \'NOTCH\' THEN \'Classic\' WHEN \'POLO\' THEN \'Polo\' WHEN \'ROUND\' THEN \'Round\' WHEN \'SHAWL\' THEN \'Others\' WHEN \'SPREAD\' THEN \'Classic\' WHEN \'TURTLENECK\' THEN \'High Neck\' WHEN \'V NECK\' THEN \'V_Neck\' WHEN \'V-NECK\' THEN \'V_Neck\' WHEN \'ZIP\' THEN \'Zip\' ELSE e.collar END END AS collar_new, CASE WHEN UPPER(TRIM(e.category)) = \'CARGO PANTS\' AND UPPER(TRIM(REGEXP_REPLACE(e.fit,\'\\s+\',\' \'))) IN (\'COMFORT FIT\',\'LOOSE FIT\') THEN \'Relaxed Fit\' WHEN UPPER(TRIM(e.category)) = \'JACKETS\' AND UPPER(TRIM(REGEXP_REPLACE(e.fit,\'\\s+\',\' \'))) = \'LOOSE FIT\' THEN \'Oversized Fit\' WHEN UPPER(TRIM(e.category)) IN (\'CO-ORDS\',\'T-SHIRTS\') AND UPPER(TRIM(REGEXP_REPLACE(e.fit,\'\\s+\',\' \'))) = \'RELAXED FIT\' THEN \'Oversized Fit\' WHEN e.fit IS NULL OR TRIM(e.fit) = \'\' THEN \'No Fit\' ELSE CASE UPPER(TRIM(REGEXP_REPLACE(e.fit,\'\\s+\',\' \'))) WHEN \'BAGGY FIT\' THEN \'Baggy Fit\' WHEN \'BALLOON FIT\' THEN \'Balloon Fit\' WHEN \'BELLBOTTOM FIT\' THEN \'Bellbottom Fit\' WHEN \'BOOTCUT\' THEN \'Bootcut\' WHEN \'BOX FIT\' THEN \'Oversized Fit\' WHEN \'CARROT FIT\' THEN \'Carrot Fit\' WHEN \'COMFORT FIT\' THEN \'Comfort Fit\' WHEN \'CROPPED OVERSIZED FIT\' THEN \'Oversized Fit\' WHEN \'CUSTOM FIT\' THEN \'Custom Fit\' WHEN \'CUSTOM REGULAR FIT\' THEN \'Regular Fit\' WHEN \'CUSTOM RELAXED FIT\' THEN \'Relaxed Fit\' WHEN \'CUSTOM SLIM FIT\' THEN \'Slim Fit\' WHEN \'CUSTOM STRAIGHT FIT\' THEN \'Straight Fit\' WHEN \'FLARED FIT\' THEN \'Flared Fit\' WHEN \'LOOSE FIT\' THEN \'Loose Fit\' WHEN \'OVERSHIRT FIT\' THEN \'Oversized Fit\' WHEN \'OVERSIZED FIT\' THEN \'Oversized Fit\' WHEN \'REGULAR FIT\' THEN \'Regular Fit\' WHEN \'REGULAR KURTA FIT\' THEN \'Regular Fit\' WHEN \'RELAXED FIT\' THEN \'Relaxed Fit\' WHEN \'SKINNY FIT\' THEN \'Skinny Fit\' WHEN \'SLIM FIT\' THEN \'Slim Fit\' WHEN \'SLOUCHY FIT\' THEN \'Slouchy Fit\' WHEN \'STRAIGHT FIT\' THEN \'Straight Fit\' WHEN \'STRAIGHT LOOSE FIT\' THEN \'Straight Loose Fit\' WHEN \'SUPER BAGGY FIT\' THEN \'Super Baggy Fit\' WHEN \'TAPERED FIT\' THEN \'Tapered Fit\' WHEN \'WIDE FIT\' THEN \'Wide Fit\' WHEN \'WIDE LEG\' THEN \'Wide Fit\' ELSE UPPER(TRIM(e.fit)) END END AS fit, CASE WHEN UPPER(TRIM(e.category)) NOT IN (\'BLAZERS\',\'BOXERS\',\'CARGO PANTS\',\'CHINOS\',\'HOODIES\',\'JACKETS\',\'JEANS\',\'JOGGERS & TRACKPANTS\',\'OVERSHIRT\',\'PYJAMAS\',\'SHIRTS\',\'SHORTS\',\'SWEATERS\',\'SWEATSHIRTS\',\'T-SHIRTS\',\'TROUSERS\') THEN \'No_Material\' WHEN UPPER(e.title) LIKE \'%LINEN%\' THEN \'Linen\' WHEN e.material IS NULL OR TRIM(e.material) = \'\' THEN \'No_Material\' ELSE CASE UPPER(TRIM(REGEXP_REPLACE(e.material,\'\\s+\',\' \'))) WHEN \'ACRYLIC\' THEN \'Acrylic\' WHEN \'ACRYLIC BLEND\' THEN \'Acrylic\' WHEN \'COTTON\' THEN \'Cotton\' WHEN \'COTTON BELND\' THEN \'Cotton\' WHEN \'COTTON BLEND\' THEN \'Cotton\' WHEN \'COTTON POLY BLEND\' THEN \'Polyester\' WHEN \'LINEN\' THEN \'Linen\' WHEN \'LINEN BLEND\' THEN \'Linen\' WHEN \'LYOCELL\' THEN \'Lyocell\' WHEN \'LYOCELL BLEND\' THEN \'Lyocell\' WHEN \'MARINO BLEND\' THEN \'Marino\' WHEN \'MELANGE\' THEN \'Cotton\' WHEN \'MODAL\' THEN \'Modal\' WHEN \'NYLON\' THEN \'Nylon\' WHEN \'NYLON BLEND\' THEN \'Nylon\' WHEN \'POLY BLEND\' THEN \'Polyester\' WHEN \'POLYESTER\' THEN \'Polyester\' WHEN \'POLYESTER BLEND\' THEN \'Polyester\' WHEN \'RAYON\' THEN \'Rayon\' WHEN \'RAYON BLEND\' THEN \'Rayon\' WHEN \'SATIN\' THEN \'Satin\' WHEN \'SATIN BLEND\' THEN \'Satin\' WHEN \'SUPIMA COTTON\' THEN \'Cotton\' WHEN \'TENCEL\' THEN \'Tencel\' WHEN \'TENCEL BLEND\' THEN \'Tencel\' WHEN \'TENCIL\' THEN \'Tencel\' WHEN \'TERRY\' THEN \'Terry\' WHEN \'TERRY BLEND\' THEN \'Terry\' WHEN \'VISCOSE\' THEN \'Viscose\' WHEN \'VISCOSE BLEND\' THEN \'Viscose\' ELSE e.material END END AS material, CASE WHEN e.sleeves_type IS NULL OR TRIM(e.sleeves_type) = \'\' THEN \'No_Sleeve\' ELSE CASE UPPER(TRIM(REGEXP_REPLACE(e.sleeves_type,\'\\s+\',\' \'))) WHEN \'ELBOW SLEEVE\' THEN \'Half Sleeve\' WHEN \'FULL SLEEVE\' THEN \'Full Sleeve\' WHEN \'HALF SLEEVE\' THEN \'Half Sleeve\' WHEN \'SLEEVELESS\' THEN \'Sleeveless\' WHEN \'THREE-QUARTER SLEEVES\' THEN \'Full Sleeve\' ELSE e.sleeves_type END END AS sleeve_length, CASE UPPER(TRIM(REGEXP_REPLACE(e.color,\'\\s+\',\' \'))) WHEN \'BEIGE\' THEN \'Beige\' WHEN \'CREAM\' THEN \'Beige\' WHEN \'CREAM BEIGE\' THEN \'Beige\' WHEN \'LIGHT BEIGE\' THEN \'Beige\' WHEN \'BLACK\' THEN \'Black\' WHEN \'BLUE\' THEN \'Blue\' WHEN \'BLUE GREY\' THEN \'Blue\' WHEN \'DARK BLUE\' THEN \'Blue\' WHEN \'DARK TEAL\' THEN \'Blue\' WHEN \'INDIGO\' THEN \'Blue\' WHEN \'LIGHT BLUE\' THEN \'Blue\' WHEN \'NAVY\' THEN \'Blue\' WHEN \'NAVY BLUE\' THEN \'Blue\' WHEN \'SKY BLUE\' THEN \'Blue\' WHEN \'TEAL\' THEN \'Blue\' WHEN \'TEAL BLUE\' THEN \'Blue\' WHEN \'TURQUOISE\' THEN \'Blue\' WHEN \'BROWN\' THEN \'Brown\' WHEN \'DARK BROWN\' THEN \'Brown\' WHEN \'HAZELNUT\' THEN \'Brown\' WHEN \'LIGHT BROWN\' THEN \'Brown\' WHEN \'SAND\' THEN \'Brown\' WHEN \'STONE\' THEN \'Brown\' WHEN \'TAN\' THEN \'Brown\' WHEN \'TAUPE\' THEN \'Brown\' WHEN \'GOLD\' THEN \'Gold\' WHEN \'DARK GREEN\' THEN \'Green\' WHEN \'GREEN\' THEN \'Green\' WHEN \'LIGHT GREEN\' THEN \'Green\' WHEN \'LIME GREEN\' THEN \'Green\' WHEN \'MINT\' THEN \'Green\' WHEN \'MINT GREEN\' THEN \'Green\' WHEN \'SAGE\' THEN \'Green\' WHEN \'SAGE GREEN\' THEN \'Green\' WHEN \'ASH GREY\' THEN \'Grey\' WHEN \'CHARCOAL GREY\' THEN \'Grey\' WHEN \'DARK GREY\' THEN \'Grey\' WHEN \'GRAY\' THEN \'Grey\' WHEN \'GREY\' THEN \'Grey\' WHEN \'GREYISH BLUE\' THEN \'Grey\' WHEN \'LIGHT GREY\' THEN \'Grey\' WHEN \'OLIVE GREY\' THEN \'Grey\' WHEN \'IVORY\' THEN \'Ivory\' WHEN \'KHAKI\' THEN \'Khaki\' WHEN \'LAVENDER\' THEN \'Lavender\' WHEN \'LAVENDER,DEFAULT TITLE\' THEN \'Lavender\' WHEN \'LILAC\' THEN \'Lavender\' WHEN \'MAUV\' THEN \'Lavender\' WHEN \'MAUVE\' THEN \'Lavender\' WHEN \'BURGUNDY\' THEN \'Maroon\' WHEN \'MAGENTA\' THEN \'Maroon\' WHEN \'MAROON\' THEN \'Maroon\' WHEN \'MULTI\' THEN \'Multi\' WHEN \'MULTICOLOR\' THEN \'Multi\' WHEN \'MULTICOLOUR\' THEN \'Multi\' WHEN \'OFF WHITE\' THEN \'Off-White\' WHEN \'OFF-WHITE\' THEN \'Off-White\' WHEN \'OLIVE\' THEN \'Olive\' WHEN \'OLIVE GREEN\' THEN \'Olive\' WHEN \'ORANGE\' THEN \'Orange\' WHEN \'RUST ORANGE\' THEN \'Orange\' WHEN \'BAKED CLAY\' THEN \'Others\' WHEN \'CHARCOAL\' THEN \'Others\' WHEN \'STAINLESS STEEL\' THEN \'Others\' WHEN \'LIGHT PINK\' THEN \'Pink\' WHEN \'PEACH\' THEN \'Pink\' WHEN \'PINK\' THEN \'Pink\' WHEN \'PURPLE\' THEN \'Purple\' WHEN \'VIOLET\' THEN \'Purple\' WHEN \'WINE\' THEN \'Purple\' WHEN \'RED\' THEN \'Red\' WHEN \'RED AND BLACK\' THEN \'Red\' WHEN \'RUST\' THEN \'Red\' WHEN \'SILVER\' THEN \'Silver\' WHEN \'NUDE\' THEN \'White\' WHEN \'WHITE\' THEN \'White\' WHEN \'MUSTARD\' THEN \'Yellow\' WHEN \'YELLOW\' THEN \'Yellow\' ELSE \'No_Colour\' END AS colour FROM enriched e LEFT JOIN snitch_db.maplemonk.offline_git_collection gc ON UPPER(TRIM(e.sku_group)) = UPPER(TRIM(gc.sku_group)) QUALIFY ROW_NUMBER() OVER (PARTITION BY UPPER(TRIM(e.sku_group)) ORDER BY gc.collection NULLS LAST) = 1 ), master_sku_mrp AS ( SELECT UPPER(CASE WHEN UPPER(SKU::STRING) LIKE \'4MTL000%\' THEN SKU::STRING WHEN UPPER(SKU::STRING) LIKE \'4C-%\' OR UPPER(SKU::STRING) LIKE \'MP-%\' OR UPPER(SKU::STRING) LIKE \'FK-%\' THEN SPLIT_PART(SKU::STRING,\'-\',1)||\'-\'||SPLIT_PART(SKU::STRING,\'-\',2)||\'-\'||SPLIT_PART(SKU::STRING,\'-\',3) WHEN UPPER(SKU::STRING) LIKE \'SH%\' THEN LEFT(SKU::STRING, LENGTH(UPPER(SKU::STRING)) - POSITION(\'-\' IN REVERSE(UPPER(SKU::STRING)))) WHEN POSITION(\'-\' IN SKU::STRING) > 0 THEN SPLIT_PART(SKU::STRING,\'-\',1)||\'-\'||SPLIT_PART(SKU::STRING,\'-\',2) ELSE SKU::STRING END) AS sku_group, MAX(mrp) AS mrp, MAX(COST_PRICE) AS cogs FROM snitch_db.maplemonk.UC_FINAL_ITEM_MASTER GROUP BY 1 ), master_ageing AS ( SELECT UPPER(sku_group) AS sku_group, MAX(weighted_ageing_days) AS ageing FROM snitch_db.maplemonk.fifo_ageing_v1 GROUP BY 1 ), live_date_pre AS ( SELECT CASE WHEN UPPER(TRIM(value:sku::STRING)) LIKE \'4MTL000%\' THEN TRIM(value:sku::STRING) WHEN UPPER(value:sku::STRING) LIKE \'4C-%\' OR UPPER(value:sku::STRING) LIKE \'MP-%\' OR UPPER(value:sku::STRING) LIKE \'FK-%\' THEN SPLIT_PART(value:sku::STRING,\'-\',1)||\'-\'||SPLIT_PART(value:sku::STRING,\'-\',2)||\'-\'||SPLIT_PART(value:sku::STRING,\'-\',3) WHEN UPPER(value:sku::STRING) LIKE \'SH%\' THEN LEFT(value:sku::STRING, LENGTH(UPPER(value:sku::STRING)) - POSITION(\'-\' IN REVERSE(UPPER(value:sku::STRING)))) WHEN POSITION(\'-\' IN value:sku::STRING) > 0 THEN SPLIT_PART(value:sku::STRING,\'-\',1)||\'-\'||SPLIT_PART(value:sku::STRING,\'-\',2) ELSE value:sku::STRING END AS sku_group, MIN(PUBLISHEDAT::DATE) AS live_date, LOWER(status) AS status FROM snitch_db.maplemonk.new_meafields_product_products_graph_ql, LATERAL FLATTEN(input => PARSE_JSON(variants)) AS value GROUP BY 1, 3 ), sku_count AS ( SELECT sku_group, COUNT(*) AS status_count FROM live_date_pre GROUP BY 1 ), live_date_main AS ( SELECT UPPER(TRIM(a.sku_group)) AS sku_group, a.status, a.live_date, ROW_NUMBER() OVER (PARTITION BY a.sku_group ORDER BY a.live_date DESC) AS rn, b.status_count FROM live_date_pre a LEFT JOIN sku_count b ON a.sku_group = b.sku_group ), final_live_date_pre AS ( SELECT sku_group, status, live_date AS final_live_date FROM live_date_main WHERE (status_count > 1 AND rn = 2) OR (status_count = 1 AND rn = 1) ), first_sales AS ( SELECT UPPER(CASE WHEN UPPER(TRIM(sku::STRING)) LIKE \'4MTL000%\' THEN TRIM(sku::STRING) WHEN UPPER(sku::STRING) LIKE \'4C-%\' OR UPPER(sku::STRING) LIKE \'MP-%\' OR UPPER(sku::STRING) LIKE \'FK-%\' THEN SPLIT_PART(sku::STRING, \'-\', 1) || \'-\' || SPLIT_PART(sku::STRING, \'-\', 2) || \'-\' || SPLIT_PART(sku::STRING, \'-\', 3) WHEN UPPER(sku::STRING) LIKE \'SH%\' THEN LEFT(sku::STRING, LENGTH(UPPER(sku::STRING)) - POSITION(\'-\' IN REVERSE(UPPER(sku::STRING)))) WHEN POSITION(\'-\' IN sku::STRING) > 0 THEN SPLIT_PART(sku::STRING, \'-\', 1) || \'-\' || SPLIT_PART(sku::STRING, \'-\', 2) ELSE sku::STRING END) AS sku_group, MIN(order_timestamp::DATE) AS first_order_date FROM snitch_db.maplemonk.fact_items_snitch GROUP BY 1 ), final_live_date AS ( SELECT a.sku_group, a.status, CASE WHEN b.first_order_date IS NULL THEN a.final_live_date WHEN a.final_live_date IS NULL THEN b.first_order_date ELSE LEAST(a.final_live_date, b.first_order_date) END AS final_live_date, DATEDIFF(DAY, CASE WHEN b.first_order_date IS NULL THEN a.final_live_date WHEN a.final_live_date IS NULL THEN b.first_order_date ELSE LEAST(a.final_live_date, b.first_order_date) END, CURRENT_DATE) AS days_since_live FROM final_live_date_pre a LEFT JOIN first_sales b ON a.sku_group = b.sku_group ), discount_sheet AS ( SELECT UPPER(TRIM(\"SKU Group\")) AS sku_group, UPPER(TRIM(category)) AS sheet_category FROM snitch_db.maplemonk.final_discount_skus_sheet1 WHERE \"SKU Group\" IS NOT NULL AND category IS NOT NULL QUALIFY ROW_NUMBER() OVER ( PARTITION BY UPPER(TRIM(\"SKU Group\")) ORDER BY CASE UPPER(TRIM(category)) WHEN \'COLLECTION\' THEN 1 WHEN \'ONLINE_NOOS\' THEN 2 WHEN \'BDAY_SALE\' THEN 3 WHEN \'EOSS\' THEN 4 ELSE 5 END, UPPER(TRIM(category)) ) = 1 ), sku_static AS ( SELECT u.sku_group, m.product_name, CASE WHEN UPPER(TRIM(u.sku_group)) LIKE \'4MSFR%\' THEN \'PERFUMES\' WHEN UPPER(TRIM(u.sku_group)) LIKE \'SN%\' THEN \'SUNGLASSES\' ELSE m.category END AS category, m.collection, m.designs, m.collar_new, m.fit, m.material, m.sleeve_length, m.colour, CASE WHEN UPPER(m.category) IN (\'BAGS\',\'BELTS\',\'ACCESSORIES\',\'PERFUMES\',\'SHOES\',\'SUNGLASSES\',\'LUGGAGE\') OR UPPER(u.sku_group) LIKE \'4MSFR%\' OR UPPER(u.sku_group) LIKE \'SN%\' OR UPPER(u.sku_group) LIKE \'BP%\' OR UPPER(u.sku_group) LIKE \'SH0%\' OR UPPER(u.sku_group) LIKE \'4MCP%\' THEN \'Long_Tail\' WHEN u.sku_group LIKE \'4MLX%\' OR u.sku_group LIKE \'4LRN%\' OR u.sku_group LIKE \'4LPL%\' OR u.sku_group LIKE \'4LTR%\' OR u.sku_group LIKE \'4LCH%\' OR u.sku_group LIKE \'4LJE%\' OR u.sku_group LIKE \'4LJK%\' OR u.sku_group LIKE \'4LSW%\' OR u.sku_group LIKE \'4LHD%\' OR u.sku_group LIKE \'4LOS%\' OR u.sku_group LIKE \'4LSHS%\' OR u.sku_group LIKE \'4LSFS%\' OR u.sku_group LIKE \'4LSH%\' OR u.sku_group LIKE \'4LBL%\' OR u.sku_group LIKE \'4LCA%\' OR u.sku_group LIKE \'4LSWT%\' OR u.sku_group LIKE \'4LCD%\' OR u.sku_group LIKE \'4LJO%\' THEN \'Luxe\' WHEN u.sku_group LIKE \'4MBG%\' OR u.sku_group LIKE \'%4BJ002%\' OR u.sku_group LIKE \'4BRN%\' OR u.sku_group LIKE \'4BPL%\' OR u.sku_group LIKE \'4BTR%\' OR u.sku_group LIKE \'4BCH%\' OR u.sku_group LIKE \'4BJE%\' OR u.sku_group LIKE \'4BJK%\' OR u.sku_group LIKE \'4BSW%\' OR u.sku_group LIKE \'4BHD%\' OR u.sku_group LIKE \'4BOS%\' OR u.sku_group LIKE \'4BSHS%\' OR u.sku_group LIKE \'4BSFS%\' OR u.sku_group LIKE \'4BSH%\' OR u.sku_group LIKE \'4BBL%\' OR u.sku_group LIKE \'4BCA%\' OR u.sku_group LIKE \'4BSWT%\' OR u.sku_group LIKE \'4BCD%\' OR u.sku_group LIKE \'4BJO%\' THEN \'Plus\' WHEN u.sku_group LIKE \'MP%\' OR u.sku_group LIKE \'FK%\' THEN \'MP\' ELSE \'Snitch\' END AS style, CASE WHEN ds.sheet_category = \'COLLECTION\' THEN \'Collection\' WHEN ds.sheet_category = \'ONLINE_NOOS\' THEN \'Online_NOOS\' WHEN ds.sheet_category = \'BDAY_SALE\' THEN \'BDay_Sale\' WHEN ds.sheet_category = \'EOSS\' THEN \'EOSS\' WHEN ds.sheet_category IS NOT NULL THEN ds.sheet_category ELSE \'Fresh\' END AS allocation_status, CASE WHEN u.sku_group = \'4MSNJ0054-01\' THEN \'https://cdn.shopify.com/s/files/1/0420/7073/7058/products/01_6fce8444-9c53-44c6-b340-fb9abf2e0ccb.jpg?v=1660722754\' ELSE pi.image_url END AS image_link, sm.mrp, sm.cogs, ag.ageing AS ageing, fld.final_live_date, fld.days_since_live FROM ( SELECT DISTINCT UPPER(TRIM( CASE WHEN UPPER(TRIM(SKU)) LIKE \'4MTL000%\' THEN TRIM(SKU) WHEN UPPER(SKU) LIKE \'4C-%\' OR UPPER(SKU) LIKE \'MP-%\' OR UPPER(SKU) LIKE \'FK-%\' THEN SPLIT_PART(SKU,\'-\',1)||\'-\'||SPLIT_PART(SKU,\'-\',2)||\'-\'||SPLIT_PART(SKU,\'-\',3) WHEN UPPER(SKU) LIKE \'SH%\' THEN LEFT(SKU, LENGTH(UPPER(SKU)) - POSITION(\'-\' IN REVERSE(UPPER(SKU)))) WHEN POSITION(\'-\' IN SKU) > 0 THEN SPLIT_PART(SKU,\'-\',1)||\'-\'||SPLIT_PART(SKU,\'-\',2) ELSE SKU END )) AS sku_group FROM SNITCH_DB.MAPLEMONK.UC_FINAL_ITEM_MASTER WHERE SKU IS NOT NULL ) u LEFT JOIN master_metafields m ON m.sku_group = u.sku_group LEFT JOIN image_map pi ON pi.sku_group = u.sku_group LEFT JOIN master_sku_mrp sm ON sm.sku_group = u.sku_group LEFT JOIN master_ageing ag ON ag.sku_group = u.sku_group LEFT JOIN final_live_date fld ON fld.sku_group = u.sku_group LEFT JOIN discount_sheet ds ON ds.sku_group = u.sku_group ) SELECT UPPER(sku_group) AS sku_group, UPPER(product_name) AS product_name, UPPER(category) AS category, UPPER(collection) AS collection, UPPER(designs) AS designs, UPPER(collar_new) AS collar_new, UPPER(fit) AS fit, UPPER(material) AS material, UPPER(sleeve_length) AS sleeve_length, UPPER(colour) AS colour, UPPER(style) AS style, UPPER(allocation_status) AS allocation_status, image_link, mrp, cogs, ageing, final_live_date, days_since_live FROM sku_static WHERE sku_group NOT LIKE \'DUMMY%\' AND sku_group NOT LIKE \'NT%\' AND sku_group NOT LIKE \'PJ%\' AND sku_group NOT LIKE \'PSTB%\' AND sku_group NOT LIKE \'%WBC%\' AND sku_group NOT LIKE \'RM%\' AND sku_group NOT LIKE \'TEST%\' AND sku_group NOT LIKE \'%UNIFORM%\' AND sku_group NOT LIKE \'8%\' AND sku_group NOT LIKE \'INK%\' AND sku_group NOT LIKE \'KIT%\' AND sku_group NOT LIKE \'MXP%\' AND sku_group NOT LIKE \'MPB%\' AND sku_group NOT LIKE \'N0%\' AND sku_group NOT LIKE \'CB%\' AND sku_group NOT LIKE \'CARGO%\' AND sku_group NOT LIKE \'CHINOS%\' AND sku_group NOT LIKE \'DENIM%\' AND sku_group NOT LIKE \'GIFT%\' AND sku_group NOT LIKE \'GV%\' AND sku_group NOT LIKE \'%INK%\' AND sku_group NOT LIKE \'%HANGERS%\' AND sku_group NOT LIKE \'%STICKER%\' AND sku_group NOT LIKE \'%BOXERS%\' AND sku_group NOT LIKE \'%XYZ%\' QUALIFY ROW_NUMBER() OVER (PARTITION BY sku_group ORDER BY final_live_date) = 1; CREATE OR REPLACE TABLE snitch_db.maplemonk.t_q1_pivot AS WITH wh_zone AS ( SELECT warehouse_location AS region, UPPER(sku_group) AS sku_group, SUM(sellable_inventory) AS wh_inventory, SUM(xs_units) AS wh_xs, SUM(s_units) AS wh_s, SUM(m_units) AS wh_m, SUM(l_units) AS wh_l, SUM(xl_units) AS wh_xl, SUM(xxl_units) AS wh_xxl, SUM(xl3_units) AS wh_3xl, SUM(xl4_units) AS wh_4xl, SUM(xl5_units) AS wh_5xl, SUM(xl6_units) AS wh_6xl, SUM(xl7_units) AS wh_7xl, SUM(xl8_units) AS wh_8xl, MIN(category) AS category, MIN(product_name) AS product_name, MIN(live_date) AS live_date FROM snitch_db.maplemonk.availability_master_v2_merged WHERE warehouse_location IN (\'North\', \'South\') GROUP BY 1, 2 ), offline_zone AS ( SELECT s.zone AS region, UPPER(o.sku_group) AS sku_group, SUM(o.inventory + o.jit_qty) AS offline_inventory, COUNT(DISTINCT CASE WHEN (o.inventory + o.jit_qty) > 0 THEN o.branch_code END) AS store_count, COUNT(DISTINCT o.branch_code) AS historical_store_count, SUM(o.xs_units + o.jit_xs_units) AS offline_xs, SUM(o.s_units + o.jit_s_units) AS offline_s, SUM(o.m_units + o.jit_m_units) AS offline_m, SUM(o.l_units + o.jit_l_units) AS offline_l, SUM(o.xl_units + o.jit_xl_units) AS offline_xl, SUM(o.xxl_units + o.jit_2xl_units) AS offline_xxl, SUM(o.xl3_units + o.jit_3xl_units) AS offline_3xl, SUM(o.xl4_units + o.jit_4xl_units) AS offline_4xl, SUM(o.xl5_units + o.jit_5xl_units) AS offline_5xl, SUM(o.xl6_units + o.jit_6xl_units) AS offline_6xl FROM snitch_db.maplemonk.offline_master o JOIN ( SELECT DISTINCT branch_code, zone FROM snitch_db.maplemonk.store_category_delta ) s ON o.branch_code = s.branch_code WHERE s.zone IN (\'North\', \'South\') GROUP BY 1, 2 ), zone_universe AS ( SELECT sku_group AS sku_group_u, region FROM wh_zone UNION SELECT sku_group AS sku_group_u, region FROM offline_zone ), q1 AS ( SELECT u.sku_group_u AS sku_group, u.region, w.live_date AS live_date, COALESCE(w.wh_inventory, 0) AS wh_inventory, COALESCE(w.wh_xs, 0) AS wh_xs, COALESCE(w.wh_s, 0) AS wh_s, COALESCE(w.wh_m, 0) AS wh_m, COALESCE(w.wh_l, 0) AS wh_l, COALESCE(w.wh_xl, 0) AS wh_xl, COALESCE(w.wh_xxl, 0) AS wh_xxl, COALESCE(w.wh_3xl, 0) AS wh_3xl, COALESCE(w.wh_4xl, 0) AS wh_4xl, COALESCE(w.wh_5xl, 0) AS wh_5xl, COALESCE(w.wh_6xl, 0) AS wh_6xl, COALESCE(w.wh_7xl, 0) AS wh_7xl, COALESCE(w.wh_8xl, 0) AS wh_8xl, COALESCE(o.offline_inventory, 0) AS offline_inventory, COALESCE(o.store_count, 0) AS store_count, COALESCE(o.historical_store_count, 0) AS historical_store_count, COALESCE(o.offline_xs, 0) AS offline_xs, COALESCE(o.offline_s, 0) AS offline_s, COALESCE(o.offline_m, 0) AS offline_m, COALESCE(o.offline_l, 0) AS offline_l, COALESCE(o.offline_xl, 0) AS offline_xl, COALESCE(o.offline_xxl, 0) AS offline_xxl, COALESCE(o.offline_3xl, 0) AS offline_3xl, COALESCE(o.offline_4xl, 0) AS offline_4xl, COALESCE(o.offline_5xl, 0) AS offline_5xl, COALESCE(o.offline_6xl, 0) AS offline_6xl FROM zone_universe u LEFT JOIN wh_zone w ON w.sku_group = u.sku_group_u AND w.region = u.region LEFT JOIN offline_zone o ON o.sku_group = u.sku_group_u AND o.region = u.region WHERE COALESCE(w.wh_inventory, 0) + COALESCE(o.offline_inventory, 0) > 0 AND u.sku_group_u NOT LIKE \'8909%\' ) SELECT sku_group, MIN(live_date) AS live_date, SUM(wh_inventory + offline_inventory) AS total_inv_all, SUM(wh_inventory) AS wh_inv_all, SUM(offline_inventory) AS offline_inv_all, SUM(store_count) AS store_count_all, SUM(historical_store_count) AS store_count_historical, SUM(wh_xs + offline_xs) AS xs_all, SUM(wh_s + offline_s) AS s_all, SUM(wh_m + offline_m) AS m_all, SUM(wh_l + offline_l) AS l_all, SUM(wh_xl + offline_xl) AS xl_all, SUM(wh_xxl + offline_xxl) AS xxl_all, SUM(wh_3xl + offline_3xl) AS xl3_all, SUM(wh_4xl + offline_4xl) AS xl4_all, SUM(wh_5xl + offline_5xl) AS xl5_all, SUM(wh_6xl + offline_6xl) AS xl6_all, SUM(wh_7xl) AS xl7_all, SUM(wh_8xl) AS xl8_all, SUM(wh_xs) AS wh_xs_all, SUM(wh_s) AS wh_s_all, SUM(wh_m) AS wh_m_all, SUM(wh_l) AS wh_l_all, SUM(wh_xl) AS wh_xl_all, SUM(wh_xxl) AS wh_xxl_all, SUM(wh_3xl) AS wh_xl3_all, SUM(wh_4xl) AS wh_xl4_all, SUM(wh_5xl) AS wh_xl5_all, SUM(wh_6xl) AS wh_xl6_all, SUM(CASE WHEN region = \'North\' THEN wh_inventory + offline_inventory ELSE 0 END) AS total_inv_north, SUM(CASE WHEN region = \'North\' THEN wh_inventory ELSE 0 END) AS wh_inv_north, SUM(CASE WHEN region = \'North\' THEN offline_inventory ELSE 0 END) AS offline_inv_north, SUM(CASE WHEN region = \'North\' THEN store_count ELSE 0 END) AS store_count_north, SUM(CASE WHEN region = \'North\' THEN historical_store_count ELSE 0 END) AS historical_store_count_north, SUM(CASE WHEN region = \'South\' THEN wh_inventory + offline_inventory ELSE 0 END) AS total_inv_south, SUM(CASE WHEN region = \'South\' THEN wh_inventory ELSE 0 END) AS wh_inv_south, SUM(CASE WHEN region = \'South\' THEN offline_inventory ELSE 0 END) AS offline_inv_south, SUM(CASE WHEN region = \'South\' THEN store_count ELSE 0 END) AS store_count_south, SUM(CASE WHEN region = \'South\' THEN historical_store_count ELSE 0 END) AS historical_store_count_south FROM q1 GROUP BY sku_group; CREATE OR REPLACE TABLE snitch_db.maplemonk.t_q2 AS WITH po_data AS ( SELECT po_date, zone, sku_group, po_qty FROM ( SELECT COALESCE( TRY_TO_DATE(SPLIT_PART(TRIM(PO_DATE::STRING),\' \',1), \'DD-MM-YYYY\'), TRY_TO_DATE(SPLIT_PART(TRIM(PO_DATE::STRING),\' \',1), \'DD/MM/YYYY\'), TRY_TO_DATE(SPLIT_PART(TRIM(PO_DATE::STRING),\' \',1), \'YYYY-MM-DD\'), TRY_TO_DATE(SPLIT_PART(TRIM(PO_DATE::STRING),\' \',1), \'DD-MON-YYYY\'), TRY_TO_DATE(SPLIT_PART(TRIM(PO_DATE::STRING),\' \',1), \'DD-MM-YY\')) AS po_date, CASE WHEN UPPER(TRIM(gowdon)) LIKE \'%NORTH%\' THEN \'NORTH\' ELSE \'SOUTH\' END AS zone, UPPER(TRIM(CASE WHEN UPPER(TRIM(sku::STRING)) LIKE \'4MTL00%\' THEN TRIM(sku::STRING) WHEN UPPER(sku::STRING) LIKE \'4C-%\' OR UPPER(sku::STRING) LIKE \'MP-%\' OR UPPER(sku::STRING) LIKE \'FK-%\' THEN SPLIT_PART(sku::STRING,\'-\',1)||\'-\'||SPLIT_PART(sku::STRING,\'-\',2)||\'-\'||SPLIT_PART(sku::STRING,\'-\',3) WHEN UPPER(sku::STRING) LIKE \'SH%\' THEN LEFT(sku::STRING, LENGTH(sku::STRING) - POSITION(\'-\' IN REVERSE(sku::STRING))) WHEN POSITION(\'-\' IN sku::STRING) > 0 THEN SPLIT_PART(sku::STRING,\'-\',1)||\'-\'||SPLIT_PART(sku::STRING,\'-\',2) ELSE sku::STRING END)) AS sku_group, TRY_TO_NUMBER(REPLACE(NULLIF(TRIM(PO_QTY::STRING), \'\'), \',\', \'\'), 38, 4) AS po_qty FROM SNITCH_DB.MAPLEMONK.S3_UC_PO WHERE sku IS NOT NULL ) WHERE po_date IS NOT NULL ), uc_po_data AS ( SELECT po_date, zone, sku_group, po_qty FROM ( SELECT COALESCE(TO_DATE(TRY_TO_TIMESTAMP(created::STRING)), COALESCE( TRY_TO_DATE(SPLIT_PART(TRIM(created::STRING),\' \',1), \'DD-MM-YYYY\'), TRY_TO_DATE(SPLIT_PART(TRIM(created::STRING),\' \',1), \'DD/MM/YYYY\'), TRY_TO_DATE(SPLIT_PART(TRIM(created::STRING),\' \',1), \'YYYY-MM-DD\'), TRY_TO_DATE(SPLIT_PART(TRIM(created::STRING),\' \',1), \'DD-MON-YYYY\'), TRY_TO_DATE(SPLIT_PART(TRIM(created::STRING),\' \',1), \'DD-MM-YY\'))) AS po_date, CASE WHEN UPPER(TRIM(facility)) LIKE \'%NORTH%\' THEN \'NORTH\' ELSE \'SOUTH\' END AS zone, UPPER(TRIM(CASE WHEN UPPER(TRIM(\"Item SkuCode\"::STRING)) LIKE \'4MTL00%\' THEN TRIM(\"Item SkuCode\"::STRING) WHEN UPPER(\"Item SkuCode\"::STRING) LIKE \'4C-%\' OR UPPER(\"Item SkuCode\"::STRING) LIKE \'MP-%\' OR UPPER(\"Item SkuCode\"::STRING) LIKE \'FK-%\' THEN SPLIT_PART(\"Item SkuCode\"::STRING,\'-\',1)||\'-\'||SPLIT_PART(\"Item SkuCode\"::STRING,\'-\',2)||\'-\'||SPLIT_PART(\"Item SkuCode\"::STRING,\'-\',3) WHEN UPPER(\"Item SkuCode\"::STRING) LIKE \'SH%\' THEN LEFT(\"Item SkuCode\"::STRING, LENGTH(\"Item SkuCode\"::STRING) - POSITION(\'-\' IN REVERSE(\"Item SkuCode\"::STRING))) WHEN POSITION(\'-\' IN \"Item SkuCode\"::STRING) > 0 THEN SPLIT_PART(\"Item SkuCode\"::STRING,\'-\',1)||\'-\'||SPLIT_PART(\"Item SkuCode\"::STRING,\'-\',2) ELSE \"Item SkuCode\"::STRING END)) AS sku_group, TRY_TO_NUMBER(REPLACE(NULLIF(TRIM(\"Recieved Quantity\"::STRING), \'\'), \',\', \'\'), 38, 4) AS po_qty FROM snitch_db.maplemonk.UC_FINAL_GET_PURCHASE_ORDERs WHERE \"Item SkuCode\" IS NOT NULL AND NOT ( UPPER(\"Vendor Name\") LIKE \'%STORE%\' OR UPPER(\"Vendor Name\") LIKE \'%RETURNS%\' OR UPPER(\"Vendor Name\") LIKE \'%SNITCH%\' OR UPPER(\"Vendor Name\") LIKE \'%MYNTRA%\' OR UPPER(\"Vendor Name\") LIKE \'%FLIPKART%\' OR UPPER(\"Vendor Name\") LIKE \'%BHARTIYA CITY%\' OR UPPER(\"Vendor Name\") LIKE \'%SAPL%\' OR UPPER(\"Vendor Name\") LIKE \'%SARATH CITY HYDERABAD%\' OR UPPER(\"Vendor Name\") LIKE \'%LULU MALL%\' OR UPPER(\"Vendor Name\") LIKE \'%PHOTOSHOOT%\' OR UPPER(\"Vendor Name\") LIKE \'%ZILO SERVICES PRIVATE LIMITED - GHATKOPAR%\' OR UPPER(\"Vendor Name\") LIKE \'%WRONG PRODUCTS%\' OR UPPER(\"Vendor Name\") LIKE \'%QCOM - DAHISAR%\' OR UPPER(\"Vendor Name\") LIKE \'%HIGHSTREET-RAJPURROAD%\' OR UPPER(\"Vendor Name\") LIKE \'%GANDHINAGAR%\' OR UPPER(\"Vendor Name\") LIKE \'%JABONG%\' OR UPPER(\"Vendor Name\") LIKE \'%EXCESS%\' OR UPPER(\"Vendor Name\") LIKE \'%CLOUDKART%\' OR UPPER(\"Vendor Name\") LIKE \'%SHIPROCKET%\' OR UPPER(\"Vendor Name\") LIKE \'%WBC%\' OR UPPER(\"Vendor Name\") LIKE \'%INSTAMART%\' OR UPPER(\"Vendor Name\") LIKE \'4M%\' ) ) WHERE po_date IS NOT NULL ), zone_combined AS ( SELECT sku_group, zone, po_date, MAX(day_qty) AS day_qty FROM ( SELECT sku_group, zone, po_date, SUM(po_qty) AS day_qty FROM po_data GROUP BY sku_group, zone, po_date UNION ALL SELECT sku_group, zone, po_date, SUM(po_qty) AS day_qty FROM uc_po_data GROUP BY sku_group, zone, po_date ) GROUP BY sku_group, zone, po_date ), pooled AS ( SELECT sku_group, po_date, SUM(day_qty) AS day_qty FROM zone_combined GROUP BY sku_group, po_date ), pooled_flagged AS ( SELECT sku_group, po_date, day_qty, SUM(day_qty) OVER (PARTITION BY sku_group) AS sku_total_qty, CASE WHEN day_qty >= 200 OR day_qty >= 0.10 * SUM(day_qty) OVER (PARTITION BY sku_group) THEN 1 ELSE 0 END AS is_real_inward FROM pooled ), zone_qualifying AS ( SELECT z.sku_group, z.zone, z.po_date FROM zone_combined z JOIN pooled_flagged f ON f.sku_group = z.sku_group AND f.po_date = z.po_date WHERE f.is_real_inward = 1 ), count_metric AS ( SELECT sku_group, MAX(zone_dates) AS inward_count FROM ( SELECT sku_group, zone, COUNT(DISTINCT po_date) AS zone_dates FROM zone_qualifying GROUP BY sku_group, zone ) GROUP BY sku_group ), last_real AS ( SELECT sku_group, po_date AS last_inward_date, day_qty AS last_inward_qty FROM pooled_flagged WHERE is_real_inward = 1 QUALIFY ROW_NUMBER() OVER (PARTITION BY sku_group ORDER BY po_date DESC) = 1 ), total_qty AS ( SELECT sku_group, SUM(day_qty) AS total_inward_qty, SUM(CASE WHEN po_date >= DATEADD(day, -30, CURRENT_DATE) AND po_date <= CURRENT_DATE THEN day_qty ELSE 0 END) AS inward_qty_l30, SUM(CASE WHEN po_date >= DATEADD(day, -60, CURRENT_DATE) AND po_date <= CURRENT_DATE THEN day_qty ELSE 0 END) AS inward_qty_l60, SUM(CASE WHEN po_date >= DATEADD(day, -90, CURRENT_DATE) AND po_date <= CURRENT_DATE THEN day_qty ELSE 0 END) AS inward_qty_l90 FROM pooled GROUP BY sku_group ), q2 AS ( SELECT t.sku_group, COALESCE(c.inward_count, 0) AS inward_count, lr.last_inward_date, lr.last_inward_qty, t.total_inward_qty, t.inward_qty_l30, t.inward_qty_l60, t.inward_qty_l90 FROM total_qty t LEFT JOIN count_metric c ON c.sku_group = t.sku_group LEFT JOIN last_real lr ON lr.sku_group = t.sku_group ) SELECT * FROM q2 WHERE sku_group NOT LIKE \'DUMMY%\' AND sku_group NOT LIKE \'NT%\' AND sku_group NOT LIKE \'PJ%\' AND sku_group NOT LIKE \'PSTB%\' AND sku_group NOT LIKE \'%WBC%\' AND sku_group NOT LIKE \'RM%\' AND sku_group NOT LIKE \'TEST%\' AND sku_group NOT LIKE \'%UNIFORM%\' AND sku_group NOT LIKE \'8%\' AND sku_group NOT LIKE \'INK%\' AND sku_group NOT LIKE \'KIT%\' AND sku_group NOT LIKE \'MXP%\' AND sku_group NOT LIKE \'MPB%\' AND sku_group NOT LIKE \'N0%\' AND sku_group NOT LIKE \'CB%\' AND sku_group NOT LIKE \'CARGO%\' AND sku_group NOT LIKE \'CHINOS%\' AND sku_group NOT LIKE \'DENIM%\' AND sku_group NOT LIKE \'GIFT%\' AND sku_group NOT LIKE \'GV%\' AND sku_group NOT LIKE \'%INK%\' AND sku_group NOT LIKE \'%HANGERS%\' AND sku_group NOT LIKE \'%STICKER%\' AND sku_group NOT LIKE \'%BOXERS%\' AND sku_group NOT LIKE \'%XYZ%\' AND sku_group NOT LIKE \'NSB%\' AND sku_group NOT LIKE \'SB%\';",
                    "transaction": true
                }
            ) }}
